function registerPackagerFactories() {
  toolsFactoryRepository.registerProjectToolFactory(new FlowToolFactory);
}

// ../flow-tool/src/services/flow-pack-service.ts
var SDK_LOG_LEVEL_MAP = {
  [0 /* DEBUG */]: "Debug" /* Debug */,
  [1 /* INFO */]: "Information" /* Info */,
  [2 /* WARN */]: "Warning" /* Warn */,
  [3 /* ERROR */]: "Error" /* Error */
};

class FlowPackService {
  fs;
  constructor() {
    this.fs = getFileSystem();
  }
  async execute(projectPath, options) {
    const [error, result] = await catchError(this.executeAsync(projectPath, options));
    if (error) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: "Flow pack failed",
        Instructions: error.message
      });
      if (error.stack) {
        logger.error("Stack trace:");
        logger.error(error.stack);
      }
      return 1;
    }
    if (!result.success) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: "Flow pack failed",
        Instructions: result.message
      });
      return 1;
    }
    OutputFormatter.success({
      Result: RESULTS.Success,
      Code: "FlowPack",
      Data: {
        Package: result.packageName ?? "",
        Output: result.outputPath ?? ""
      }
    });
    return 0;
  }
  async executeAsync(projectPath, options) {
    const absoluteProjectPath = this.fs.path.resolve(projectPath);
    const absoluteOutputPath = this.fs.path.resolve(options.output);
    const packageName = options.name || this.fs.path.basename(projectPath);
    if (!VALID_PACKAGE_NAME_REGEX.test(packageName)) {
      return {
        success: false,
        message: `Invalid package name "${packageName}". Package name can only contain letters, numbers, dots (.), underscores (_), and hyphens (-).`
      };
    }
    logger.info(`
Packing flow project...
`);
    logger.info("Details:");
    logger.info(`  Project:  ${absoluteProjectPath}`);
    logger.info(`  Package:  ${packageName}@${options.version}`);
    logger.info(`  Output:   ${absoluteOutputPath}`);
    logger.info("");
    await this.validate(absoluteProjectPath);
    const flowContent = await this.readFlowFile(absoluteProjectPath, packageName);
    ensureProcessBindings(flowContent);
    const stagingDir = this.fs.path.join(this.fs.env.tmpdir(), `.flow-pack-${packageName}-${Date.now()}`);
    await this.fs.mkdir(stagingDir);
    try {
      await this.stageProjectFiles(absoluteProjectPath, stagingDir, packageName, flowContent);
      await this.fs.mkdir(absoluteOutputPath);
      const packageId = `${packageName}.flow.Flow`;
      const version = options.version || "1.0.0";
      registerPackagerFactories();
      const { createNodeProjectPackager, ProjectPackOptions } = await import("./node-ks3095fb.js");
      const packager = await createNodeProjectPackager({
        logHandler: logger.handleLog
      });
      const packOptions = new ProjectPackOptions;
      packOptions.inputPath = stagingDir;
      packOptions.destinationPath = absoluteOutputPath;
      packOptions.logLevel = SDK_LOG_LEVEL_MAP[logger.getLevel()] ?? "Error" /* Error */;
      packOptions.package = {
        id: packageId,
        version,
        tags: "Flow",
        ...mapPackageMetadataOptions(options)
      };
      const result = await packager.packProjectAsync(packOptions);
      if (!result.isSuccess) {
        return {
          success: false,
          message: [result.message, result.instructions].filter(Boolean).join(" ") || "Flow pack failed"
        };
      }
      if (!result.packages[0]) {
        return {
          success: false,
          message: "Pack succeeded but no output package was produced"
        };
      }
      return {
        success: true,
        message: "Flow pack succeeded",
        packageName: `${packageName}@${version}`,
        outputPath: result.packages[0]
      };
    } finally {
      await this.fs.rm(stagingDir).catch((err) => {
        logger.warn(`Failed to clean up staging directory ${stagingDir}: ${err instanceof Error ? err.message : String(err)}`);
      });
    }
  }
  async stageProjectFiles(projectPath, stagingDir, projectName, flowContent) {
    const safeName = projectName.replace(/[^a-zA-Z0-9_-]/g, "_");
    const profile = await resolveRuntimeProfile(this.fs, projectPath);
    await applyRuntimeProfile(this.fs, stagingDir, profile);
    await writeFlowWorkflow(this.fs.path.join(stagingDir, `${safeName}.flow`), flowContent);
    const uiprojPath = this.fs.path.join(projectPath, "project.uiproj");
    if (await this.fs.exists(uiprojPath)) {
      await this.fs.writeFile(this.fs.path.join(stagingDir, "project.uiproj"), await this.fs.readFile(uiprojPath, "utf-8"));
    }
    const flowNodes = flowContent.nodes;
    const inlineAgents = await packageInlineAgents(this.fs, projectPath, flowNodes);
    if (inlineAgents.length > 0) {
      logger.info(`Found ${inlineAgents.length} inline agent(s) to package`);
    }
    const inlineAgentSchemas = new Map(inlineAgents.map((agent) => [agent.source, agent.agentJson]));
    await hydrateInlineAgentInputVariables(flowNodes, async (source) => inlineAgentSchemas.get(source)?.inputSchema, (source, added) => logger.info(`Reconciled ${added} inline-agent input(s) for "${source}" from agent.json inputSchema`), (source, reason) => logger.warn(reason === "invalid-source" ? `Inline agent "${source}" is not a bare project-id folder, so its inputs were not reconciled and packaging skips it — the agent would ship with no bound inputs.` : `Could not read an inputSchema for inline agent "${source}", so its inputs were not reconciled — the agent would ship with no bound inputs. Check that ${source}/agent.json exists and parses.`));
    logger.info("Converting .flow to BPMN...");
    const fileFormat = inMemoryWorkflowToFileFormat(flowContent);
    setPublishIntentOnInlineAgents(fileFormat);
    const flowJson = JSON.stringify(fileFormat, null, 2);
    const { bpmn: rawBpmn } = await convertFlowToBpmn(flowJson, voiceConvertOptions({
      flowJson,
      nodes: flowNodes,
      builtAgents: new Map(inlineAgents.map((agent) => [
        agent.source,
        agent.agentJson
      ]))
    }));
    const bpmn = replaceExporterVersion(rawBpmn, package_default.version);
    assertVoiceAgentDefinitionsEmbedded(bpmn, flowNodes);
    const bpmnFileName = `${safeName}.bpmn`;
    await this.fs.writeFile(this.fs.path.join(stagingDir, bpmnFileName), bpmn);
    logger.info("Generating packaging artifacts...");
    const packagingNodes = fileNodesToPackagingNodes(flowContent.nodes);
    const startEventId = extractStartEventId(bpmn);
    const projectId = flowContent.id || await ensureProjectId(projectPath, this.fs);
    const packageDescriptorJson = inlineAgents.length > 0 ? generatePackageDescriptor([{ name: bpmnFileName }], [{ name: `${safeName}.flow` }], inlineAgents.map((agent) => ({
      name: `${agent.source}/agent.json`
    }))) : undefined;
    await writePackagingArtifactsDetailed(this.fs, stagingDir, projectId, packagingNodes, flowContent.bindings ?? [], flowContent.variables ?? {}, bpmnFileName, startEventId, `${safeName}.flow`, flowContent.definitions ?? [], {
      additionalEntryPoints: inlineAgents.map((agent) => agent.entryPoint),
      additionalBindingsJsons: inlineAgents.map((agent) => agent.bindingsJson),
      ...packageDescriptorJson ? { packageDescriptorJson } : {},
      profile
    });
    await writeResolvedFlow(this.fs, stagingDir, safeName, flowContent);
    if (inlineAgents.length > 0) {
      await stageInlineAgentPackageFiles(this.fs, projectPath, stagingDir, inlineAgents, (source) => `Packaged inline agent "${source}"`);
      const operateContent = await this.fs.readFile(this.fs.path.join(stagingDir, "operate.json"), "utf-8");
      if (operateContent) {
        const operateJson = JSON.parse(operateContent);
        if (operateJson.main && !operateJson.main.startsWith("content/")) {
          operateJson.main = `content${operateJson.main}`;
          await this.fs.writeFile(this.fs.path.join(stagingDir, "operate.json"), `${JSON.stringify(operateJson, null, 2)}
`);
        }
      }
    }
  }
  async readFlowFile(projectPath, projectName) {
    const safeName = projectName.replace(/[^a-zA-Z0-9_-]/g, "_");
    const flowFilePath = this.fs.path.join(projectPath, `${safeName}.flow`);
    if (!await this.fs.exists(flowFilePath)) {
      throw new Error(`Missing ${safeName}.flow in: ${projectPath}`);
    }
    const { workflow } = await readFlowWorkflow(flowFilePath);
    return workflow;
  }
  async validate(projectPath) {
    if (!await this.fs.exists(projectPath)) {
      throw new Error(`Project path does not exist: ${projectPath}`);
    }
    const stats = await this.fs.stat(projectPath);
    if (!stats?.isDirectory()) {
      throw new Error(`Project path must be a directory: ${projectPath}`);
    }
  }
}
export {
  FlowPackService
};

